// Single import point for contract types. Contracts come only from the generated file
// (never hand-edit src/contracts/generated.ts); this module re-exports them and adds the
// UI-only shapes of the static demo files.
import type {
  Equipment,
  Finding,
  Material,
  Opportunity,
  Project,
  ProjectBundle,
  PurchaseRequisition,
  RunEvent,
  RunRecord,
  TopologyOption,
  WhatIfResult,
} from '@/contracts/generated'

export type {
  Approval,
  Citation,
  ClauseRef,
  Connection,
  CoolingNode,
  CrmOverlay,
  DesignBrief,
  DesignModel,
  Equipment,
  Finding,
  Geometry,
  LedgerEntry,
  Material,
  OpenQuestion,
  Opportunity,
  Pipe,
  PlanStep,
  Point3,
  PRLine,
  Project,
  ProjectBundle,
  PurchaseRequisition,
  Rack,
  Requirement,
  Revision,
  RunEvent,
  RunRecord,
  StepRecord,
  TopologyOption,
  WhatIfResult,
} from '@/contracts/generated'

export type ProjectState = Project['state']
export type AssetPack = Project['asset_pack']
export type FindingStatus = Finding['status']
export type AgentName = RunEvent['agent']
export type EventKind = RunEvent['kind']
export type Phase = RunEvent['phase']
export type EquipmentKind = Equipment['kind']
export type TopologyId = TopologyOption['id']
export type WhatIfParam = WhatIfResult['param']
export type Autonomy = RunRecord['autonomy']

/** A ProjectBundle with every optional collection filled in (see normalizeBundle). */
export type Bundle = Required<ProjectBundle>

export function normalizeBundle(b: ProjectBundle): Bundle {
  return {
    project: b.project,
    brief: b.brief ?? null,
    runs: b.runs ?? [],
    steps: b.steps ?? [],
    events: [...(b.events ?? [])].sort((x, y) => x.seq - y.seq),
    revisions: [...(b.revisions ?? [])].sort((x, y) => x.created_at - y.created_at),
    findings: b.findings ?? {},
    approvals: b.approvals ?? [],
    prs: b.prs ?? [],
    crm: b.crm ?? null,
    what_ifs: b.what_ifs ?? [],
  }
}

/** Static demo world (`public/demo/world.json`, generated by WS4). */
export interface WorldPerson {
  id: string
  name: string
  role: string
  initials?: string
}
export interface WorldActivity {
  id: string
  ts: number // unix seconds
  actor: string
  project_id?: string | null
  text: string
}
export interface World {
  org: { name: string; tagline?: string }
  people: WorldPerson[]
  projects: Project[]
  activity: WorldActivity[]
}

/** Static integrations snapshot (`public/demo/integrations.json`, generated by WS4). */
export interface DocumentRecord {
  id: string
  project_id: string
  name: string
  kind: string // "tender" | "drawing" | "calc_report" | "boq" | ...
  url: string // public URL (e.g. /demo/docs/tender-hall-a.pdf)
  updated_at: number
}
export interface NotificationRecord {
  id: string
  ts: number
  kind: string // "approval" | "finding" | ...
  title: string
  body?: string
  project_id?: string | null
}
export interface IntegrationsSnapshot {
  synced_at?: number
  erp: { materials: Material[]; prs: PurchaseRequisition[] }
  crm: { opportunities: Opportunity[] }
  documents: DocumentRecord[]
  notifications: NotificationRecord[]
}

/** Asset-pack result dict (interfaces doc: evaluate_grid/evaluate_solar; `POST /api/asset/{pack}`). */
export interface AssetResult {
  options: Record<string, unknown>[]
  recommended: string
  findings: Finding[]
  geometry: Record<string, unknown>
  sld?: { nodes: { id: string; kind: string; label: string }[]; edges: { src: string; dst: string; label?: string }[] }
  /** The Asset agent's pick (WS2 ruling R33); `source: 'engine'` when the agent fell back to `recommended`. */
  choice?: { option: string; reason: string; source: 'agent' | 'engine' }
}
